// Hilfsklasse fuer Tests und Hauptprogramm: die vier Testkarten.
// Jeder Aufruf liefert eine NEUE Karte (frisch vernebelt).
class Kartenbuch {

    // Die offene Hoehle (5 Zeilen, 7 Spalten), Start (1, 1), Ziel (3, 5):
    //       0123456
    //    0  #######
    //    1  #S....#
    //    2  #..#..#
    //    3  #....Z#
    //    4  #######
    public static Karte hoehle() {
        String[] zeilen = {
            "#######",
            "#S....#",
            "#..#..#",
            "#....Z#",
            "#######"
        };
        return new Karte(zeilen);
    }

    // Das Labyrinth (9 Zeilen, 9 Spalten), Start (1, 1), Ziel (5, 7).
    // Es gibt einen Weg, mehrere Sackgassen und unten rechts eine
    // abgeschlossene Kammer (nur UEBER ECK mit dem Gang verbunden).
    //       012345678
    //    0  #########
    //    1  #S#...#.#
    //    2  #.#.#.#.#
    //    3  #...#...#
    //    4  #.###.#.#
    //    5  #...#.#Z#
    //    6  ###.##.##
    //    7  #...#...#
    //    8  #########
    public static Karte labyrinth() {
        String[] zeilen = {
            "#########",
            "#S#...#.#",
            "#.#.#.#.#",
            "#...#...#",
            "#.###.#.#",
            "#...#.#Z#",
            "###.##.##",
            "#...#...#",
            "#########"
        };
        return new Karte(zeilen);
    }

    // Der Kerker (6 Zeilen, 8 Spalten), Start (1, 1), Ziel (2, 5).
    // KEIN Weg: Das Ziel liegt in einer eigenen Kammer.
    //       01234567
    //    0  ########
    //    1  #S..#..#
    //    2  #.#.#Z.#
    //    3  #...####
    //    4  #.#....#
    //    5  ########
    public static Karte kerker() {
        String[] zeilen = {
            "########",
            "#S..#..#",
            "#.#.#Z.#",
            "#...####",
            "#.#....#",
            "########"
        };
        return new Karte(zeilen);
    }

    // Die Lichtung (3 Zeilen, 4 Spalten), Start (1, 1), Ziel (2, 3).
    // OHNE Randmauer: Wer nicht prueft, ob (z, s) im Feld liegt, stuerzt ab.
    //       0123
    //    0  ..#.
    //    1  .S..
    //    2  #..Z
    public static Karte lichtung() {
        String[] zeilen = {
            "..#.",
            ".S..",
            "#..Z"
        };
        return new Karte(zeilen);
    }

    // Erwartete Karte als Text (Zeilen mit "\n" verbunden) - wie alsText().
    public static String text(String[] zeilen) {
        String t = "";
        for (int i = 0; i < zeilen.length; i++) {
            if (i > 0) {
                t = t + "\n";
            }
            t = t + zeilen[i];
        }
        return t;
    }
}


// ================== Level 3.1 – Rekursion (DS 18) =====================

class L31RekursionTest {

    @Test
    public void basis_fakultaet() {
        assertEquals(120, Rekursion.fakultaet(5), "fakultaet(5) = 5 * 4 * 3 * 2 * 1 = 120");
        assertEquals(6, Rekursion.fakultaet(3), "fakultaet(3) = 3 * 2 * 1 = 6");
        assertEquals(1, Rekursion.fakultaet(1), "fakultaet(1) = 1");
        assertEquals(3628800, Rekursion.fakultaet(10), "fakultaet(10) = 3628800");
    }

    @Test
    public void basis_fakultaet_basisfallNull() {
        assertEquals(1, Rekursion.fakultaet(0), "fakultaet(0) = 1 (Basisfall n = 0). Bei StackOverflowError wird dein Basisfall bei n = 0 nie erreicht");
        assertEquals(2, Rekursion.fakultaet(2), "fakultaet(2) = 2 * fakultaet(1) = 2");
    }

    @Test
    public void basis_summeBis() {
        assertEquals(10, Rekursion.summeBis(4), "summeBis(4) = 0 + 1 + 2 + 3 + 4 = 10");
        assertEquals(55, Rekursion.summeBis(10), "summeBis(10) = 55");
        assertEquals(1, Rekursion.summeBis(1), "summeBis(1) = 0 + 1 = 1");
    }

    @Test
    public void basis_summeBis_basisfallNull() {
        assertEquals(3, Rekursion.summeBis(2), "summeBis(2) = 0 + 1 + 2 = 3");
        assertEquals(0, Rekursion.summeBis(0), "summeBis(0) = 0. Bei StackOverflowError fehlt der Basisfall n = 0 (n = 1 reicht nicht)");
    }

    @Test
    public void basis_potenz() {
        assertEquals(1024, Rekursion.potenz(2, 10), "potenz(2, 10) = 1024");
        assertEquals(81, Rekursion.potenz(3, 4), "potenz(3, 4) = 3 * 3 * 3 * 3 = 81");
        assertEquals(5, Rekursion.potenz(5, 1), "potenz(5, 1) = 5");
        assertEquals(-8, Rekursion.potenz(-2, 3), "potenz(-2, 3) = (-2) * (-2) * (-2) = -8");
    }

    @Test
    public void basis_potenz_exponentNull() {
        assertEquals(1, Rekursion.potenz(7, 0), "potenz(7, 0) = 1 (Basisfall exponent = 0). Bei StackOverflowError den Basisfall pruefen!");
        assertEquals(49, Rekursion.potenz(7, 2), "potenz(7, 2) = 49");
    }

    @Test
    public void erweiterung_anzahlZiffern() {
        assertEquals(4, Rekursion.anzahlZiffern(4711), "4711 hat 4 Ziffern");
        assertEquals(1, Rekursion.anzahlZiffern(7), "7 hat 1 Ziffer");
        assertEquals(2, Rekursion.anzahlZiffern(10), "10 hat 2 Ziffern");
        assertEquals(3, Rekursion.anzahlZiffern(100), "100 hat 3 Ziffern - auch die Nullen zaehlen");
    }

    @Test
    public void erweiterung_anzahlZiffern_null() {
        assertEquals(1, Rekursion.anzahlZiffern(0), "0 hat EINE Ziffer: anzahlZiffern(0) = 1 (Basisfall n < 10, nicht n == 0)");
        assertEquals(2, Rekursion.anzahlZiffern(99), "99 hat 2 Ziffern");
    }

    @Test
    public void erweiterung_istPalindrom() {
        assertTrue(Rekursion.istPalindrom("otto"), "'otto' ist ein Palindrom (gerade Laenge)");
        assertTrue(Rekursion.istPalindrom("level"), "'level' ist ein Palindrom (ungerade Laenge)");
        assertFalse(Rekursion.istPalindrom("abc"), "'abc' ist kein Palindrom");
        assertFalse(Rekursion.istPalindrom("abca"), "'abca': erstes und letztes Zeichen gleich, aber 'bc' in der Mitte ist kein Palindrom");
        assertFalse(Rekursion.istPalindrom("Otto"), "'Otto' ist kein Palindrom: 'O' und 'o' sind verschiedene Zeichen");
    }

    @Test
    public void erweiterung_istPalindrom_randfaelle() {
        assertTrue(Rekursion.istPalindrom(""), "Die leere Zeichenkette ist ein Palindrom (Basisfall)");
        assertTrue(Rekursion.istPalindrom("x"), "Ein einzelnes Zeichen ist ein Palindrom (Basisfall)");
        assertTrue(Rekursion.istPalindrom("aa"), "'aa' ist ein Palindrom");
        assertFalse(Rekursion.istPalindrom("ab"), "'ab' ist kein Palindrom");
        assertTrue(Rekursion.istPalindrom("abcba"), "'abcba' ist ein Palindrom - bei ungerader Laenge muss der Basisfall Laenge <= 1 greifen");
    }

    @Test
    public void erweiterung_summeAb() {
        int[] r = {3, 8, 2, 5};
        assertEquals(18, Rekursion.summeAb(r, 0), "summeAb({3, 8, 2, 5}, 0) = 3 + 8 + 2 + 5 = 18");
        assertEquals(7, Rekursion.summeAb(r, 2), "summeAb({3, 8, 2, 5}, 2) = 2 + 5 = 7");
        assertEquals(5, Rekursion.summeAb(r, 3), "summeAb({3, 8, 2, 5}, 3) = 5 (nur das letzte Element)");
    }

    @Test
    public void erweiterung_summeAb_basisfall() {
        int[] r = {3, 8, 2, 5};
        assertEquals(15, Rekursion.summeAb(r, 1), "summeAb({3, 8, 2, 5}, 1) = 8 + 2 + 5 = 15");
        assertEquals(0, Rekursion.summeAb(r, 4), "summeAb(r, r.length) = 0 - Basisfall i == r.length (keine Elemente mehr)");
        assertEquals(0, Rekursion.summeAb(new int[0], 0), "Leere Reihung: summeAb(r, 0) = 0 - Basisfall i == r.length");
        int[] neg = {-4, 4, -9};
        assertEquals(-9, Rekursion.summeAb(neg, 0), "summeAb({-4, 4, -9}, 0) = -9");
    }

    @Test
    public void experte_maximumAb() {
        int[] r = {4, 9, 2, 7, 1};
        assertEquals(9, Rekursion.maximumAb(r, 0), "maximumAb({4, 9, 2, 7, 1}, 0) = 9");
        assertEquals(7, Rekursion.maximumAb(r, 2), "maximumAb({4, 9, 2, 7, 1}, 2) = 7 - erst ab Index 2 suchen");
        assertEquals(1, Rekursion.maximumAb(r, 4), "maximumAb({4, 9, 2, 7, 1}, 4) = 1 (Basisfall: letztes Element)");
    }

    @Test
    public void experte_maximumAb_raender() {
        int[] vorne = {12, 3, 5};
        int[] hinten = {3, 5, 12};
        int[] neg = {-5, -2, -8};
        assertEquals(12, Rekursion.maximumAb(vorne, 0), "Maximum ganz vorne: {12, 3, 5} -> 12");
        assertEquals(12, Rekursion.maximumAb(hinten, 0), "Maximum ganz hinten: {3, 5, 12} -> 12");
        assertEquals(-2, Rekursion.maximumAb(neg, 0), "Nur negative Werte: {-5, -2, -8} -> -2 (nicht mit 0 starten!)");
        int[] eins = {6};
        assertEquals(6, Rekursion.maximumAb(eins, 0), "Ein Element: {6} -> 6");
    }

    @Test
    public void experte_dual() {
        assertEquals("110", Rekursion.dual(6), "dual(6) = '110' (6 = 4 + 2)");
        assertEquals("1101", Rekursion.dual(13), "dual(13) = '1101' (13 = 8 + 4 + 1)");
        assertEquals("1000", Rekursion.dual(8), "dual(8) = '1000'");
        assertEquals("1", Rekursion.dual(1), "dual(1) = '1'");
    }

    @Test
    public void experte_dual_basisfall() {
        assertEquals("10", Rekursion.dual(2), "dual(2) = '10' - ohne fuehrende Null (nicht '010')");
        assertEquals("0", Rekursion.dual(0), "dual(0) = '0' (nicht die leere Zeichenkette)");
        assertEquals("11111111", Rekursion.dual(255), "dual(255) = '11111111'");
    }

    @Test
    public void experte_fibonacci() {
        assertEquals(5, Rekursion.fibonacci(5), "fibonacci(5) = 5 (0, 1, 1, 2, 3, 5)");
        assertEquals(55, Rekursion.fibonacci(10), "fibonacci(10) = 55");
        assertEquals(1, Rekursion.fibonacci(2), "fibonacci(2) = fib(1) + fib(0) = 1");
        assertEquals(1, Rekursion.fibonacci(1), "fibonacci(1) = 1 (Basisfall)");
        assertEquals(0, Rekursion.fibonacci(0), "fibonacci(0) = 0 (Basisfall)");
    }

    @Test
    public void experte_fibonacci_aufrufe() {
        Rekursion.aufrufe = 0;
        Rekursion.fibonacci(5);
        assertEquals(15, Rekursion.aufrufe, "fibonacci(5) ruft sich (mit dem ersten Aufruf) 15-mal auf - zeichne den Aufrufbaum! aufrufe++ als ERSTE Anweisung, zwei Selbstaufrufe");
        Rekursion.aufrufe = 0;
        Rekursion.fibonacci(1);
        assertEquals(1, Rekursion.aufrufe, "fibonacci(1) ist ein Basisfall: genau 1 Aufruf");
        Rekursion.aufrufe = 0;
        Rekursion.fibonacci(10);
        assertEquals(177, Rekursion.aufrufe, "fibonacci(10) braucht 177 Aufrufe - baumrekursiv waechst die Zahl der Aufrufe sehr schnell");
    }
}


