        assertEquals(0, Kartenbuch.labyrinth().anzahlGelueftet(), "Frische Karte: noch nichts gelueftet -> 0");
    }

    @Test
    public void experte_findeWeg_hoehle() {
        Karte k = Kartenbuch.hoehle();
        assertTrue(k.findeWeg(1, 1), "Hoehle: Es gibt einen Weg von S zu Z");
        String[] erwartet = {
            "#######",
            "#S****#",
            "#..#.*#",
            "#....Z#",
            "#######"
        };
        assertEquals(Kartenbuch.text(erwartet), k.alsText(), "Hoehle nach findeWeg(1, 1): Weg mit '*' (Reihenfolge oben, rechts, unten, links!), nie besuchte Felder bleiben '.'");
    }

    @Test
    public void experte_findeWeg_labyrinth() {
        Karte k = Kartenbuch.labyrinth();
        assertTrue(k.findeWeg(1, 1), "Labyrinth: Es gibt einen Weg von S zu Z");
        String[] erwartet = {
            "#########",
            "#S#***#x#",
            "#*#*#*#x#",
            "#***#***#",
            "#.###.#*#",
            "#...#.#Z#",
            "###.##.##",
            "#...#...#",
            "#########"
        };
        assertEquals(Kartenbuch.text(erwartet), k.alsText(), "Labyrinth nach findeWeg(1, 1): Weg '*', Sackgasse oben rechts 'x' (Schritt zurueckgenommen!), Rest '.'");
    }

    @Test
    public void experte_findeWeg_keinWeg() {
        Karte k = Kartenbuch.kerker();
        assertFalse(k.findeWeg(1, 1), "Kerker: Das Ziel ist nicht erreichbar - findeWeg muss false liefern");
        String[] erwartet = {
            "########",
            "#Sxx#..#",
            "#x#x#Z.#",
            "#xxx####",
            "#x#xxxx#",
            "########"
        };
        assertEquals(Kartenbuch.text(erwartet), k.alsText(), "Kerker nach findeWeg(1, 1): Alle besuchten Felder sind Sackgassen 'x', S bleibt 'S', die Zielkammer bleibt '.'");
    }

    @Test
    public void experte_findeWeg_rand() {
        Karte k = Kartenbuch.lichtung();
        assertTrue(k.findeWeg(1, 1), "Lichtung: Es gibt einen Weg von S zu Z");
        String[] erwartet = {
            "xx#x",
            "xS**",
            "#..Z"
        };
        assertEquals(Kartenbuch.text(erwartet), k.alsText(), "Lichtung nach findeWeg(1, 1): Sackgassen am Rand 'x', Weg '*'. Bei Absturz fehlt die Pruefung, ob (z, s) im Feld liegt");
    }

    @Test
    public void experte_findeWeg_schritte() {
        Karte h = Kartenbuch.hoehle();
        h.schritte = 0;
        h.findeWeg(1, 1);
        assertEquals(15, h.schritte, "Hoehle: findeWeg(1, 1) wird 15-mal aufgerufen (jeder Aufruf zaehlt - auch auf Waenden; Reihenfolge oben, rechts, unten, links; Abbruch beim ersten true)");
        Karte l = Kartenbuch.labyrinth();
        l.schritte = 0;
        l.findeWeg(1, 1);
        assertEquals(41, l.schritte, "Labyrinth: findeWeg(1, 1) wird 41-mal aufgerufen");
        Karte k = Kartenbuch.kerker();
        k.schritte = 0;
        k.findeWeg(1, 1);
        assertEquals(53, k.schritte, "Kerker (ohne Weg): findeWeg(1, 1) wird 53-mal aufgerufen");
        Karte li = Kartenbuch.lichtung();
        li.schritte = 0;
        li.findeWeg(1, 1);
        assertEquals(24, li.schritte, "Lichtung: findeWeg(1, 1) wird 24-mal aufgerufen (Aufrufe ausserhalb der Karte zaehlen mit)");
    }

    @Test
    public void experte_findeWeg_startAmZiel() {
        String[] zeilen = {"#Z.", "#.#"};
        Karte k = new Karte(zeilen);
        k.schritte = 0;
        assertTrue(k.findeWeg(0, 1), "Start direkt auf dem Ziel: findeWeg liefert sofort true");
        assertEquals(1, k.schritte, "Start direkt auf dem Ziel: genau 1 Aufruf (Basisfall)");
        assertEquals("#Z.\n#.#", k.alsText(), "Start direkt auf dem Ziel: Die Karte bleibt unveraendert");
        Karte w = Kartenbuch.hoehle();
        assertFalse(w.findeWeg(0, 0), "Start auf einer Wand: kein Weg (false)");
        assertFalse(w.findeWeg(-1, 0), "Start ausserhalb der Karte: kein Weg (false)");
    }
}


// ========= Level 3.3 – Teile und herrsche (DS 21 und 22) ==============

class L33TeileHerrscheTest {

    // Aufsteigend sortiert, n = 9:
    //   Index: 0  1   2   3   4   5   6   7   8
    //   Wert:  3  8  15  23  42  57  61  77  90
    private int[] neun() {
        int[] r = {3, 8, 15, 23, 42, 57, 61, 77, 90};
        return r;
    }

    @Test
    public void basis_binaer_gefunden() {
        int[] r = neun();
        assertEquals(4, TeileUndHerrsche.binaer(r, 42), "42 steht in der Mitte (Index 4) - schon der erste Vergleich trifft");
        assertEquals(6, TeileUndHerrsche.binaer(r, 61), "61 steht an Index 6 (rechte Haelfte)");
        assertEquals(1, TeileUndHerrsche.binaer(r, 8), "8 steht an Index 1 (linke Haelfte)");
        assertEquals(0, TeileUndHerrsche.binaer(r, 3), "3 steht ganz vorne an Index 0");
        assertEquals(8, TeileUndHerrsche.binaer(r, 90), "90 steht ganz hinten an Index 8");
    }

    @Test
    public void basis_binaer_nichtGefunden() {
        int[] r = neun();
        assertEquals(2, TeileUndHerrsche.binaer(r, 15), "15 steht an Index 2");
        assertEquals(-1, TeileUndHerrsche.binaer(r, 50), "50 kommt nicht vor: -1 (Basisfall lo > hi). Bei StackOverflowError wird der Bereich nicht kleiner (mid + 1 bzw. mid - 1!)");
        assertEquals(-1, TeileUndHerrsche.binaer(r, 1), "1 ist kleiner als alle Werte: -1");
        assertEquals(-1, TeileUndHerrsche.binaer(r, 100), "100 ist groesser als alle Werte: -1");
    }

    @Test
    public void basis_binaer_leerUndEins() {
        int[] eins = {7};
        assertEquals(0, TeileUndHerrsche.binaer(eins, 7), "Reihung {7}: 7 steht an Index 0");
        assertEquals(-1, TeileUndHerrsche.binaer(eins, 5), "Reihung {7}: 5 kommt nicht vor");
        assertEquals(-1, TeileUndHerrsche.binaer(new int[0], 5), "Leere Reihung: -1 (binaerRek(r, x, 0, -1): lo > hi)");
    }

    @Test
    public void basis_binaerRek_teilbereich() {
        int[] r = neun();
        assertEquals(5, TeileUndHerrsche.binaerRek(r, 57, 4, 8), "binaerRek(r, 57, 4, 8): 57 steht an Index 5");
        assertEquals(7, TeileUndHerrsche.binaerRek(r, 77, 5, 7), "binaerRek(r, 77, 5, 7): 77 steht an Index 7 - mid = (lo + hi) / 2, nicht (hi - lo) / 2");
        assertEquals(-1, TeileUndHerrsche.binaerRek(r, 8, 4, 8), "binaerRek(r, 8, 4, 8): 8 steht an Index 1 - also NICHT im Bereich 4 bis 8 -> -1");
        assertEquals(-1, TeileUndHerrsche.binaerRek(r, 42, 5, 4), "binaerRek(r, 42, 5, 4): lo > hi, der Bereich ist leer -> -1 (Basisfall)");
    }

    @Test
    public void erweiterung_maximumTH() {
        int[] r = {4, 9, 2, 7, 1};
        assertEquals(9, TeileUndHerrsche.maximumTH(r, 0, 4), "maximumTH({4, 9, 2, 7, 1}, 0, 4) = 9");
        assertEquals(7, TeileUndHerrsche.maximumTH(r, 2, 4), "maximumTH({4, 9, 2, 7, 1}, 2, 4) = 7 - nur im Bereich 2 bis 4 suchen");
        assertEquals(7, TeileUndHerrsche.maximumTH(r, 3, 3), "maximumTH(r, 3, 3) = r[3] = 7 (Basisfall von == bis)");
        assertEquals(9, TeileUndHerrsche.maximumTH(r, 0, 1), "maximumTH(r, 0, 1) = 9 - zwei Elemente: beide Haelften pruefen");
    }

    @Test
    public void erweiterung_maximumTH_raender() {
        int[] vorne = {12, 3, 5, 1};
        int[] hinten = {3, 5, 1, 12};
        int[] neg = {-5, -2, -8};
        assertEquals(12, TeileUndHerrsche.maximumTH(vorne, 0, 3), "Maximum ganz vorne: {12, 3, 5, 1} -> 12");
        assertEquals(12, TeileUndHerrsche.maximumTH(hinten, 0, 3), "Maximum ganz hinten: {3, 5, 1, 12} -> 12 (rechte Haelfte: mitte + 1 bis bis)");
        assertEquals(5, TeileUndHerrsche.maximumTH(vorne, 1, 3), "maximumTH({12, 3, 5, 1}, 1, 3) = 5 - die 12 liegt ausserhalb");
        assertEquals(-2, TeileUndHerrsche.maximumTH(neg, 0, 2), "Nur negative Werte: {-5, -2, -8} -> -2");
    }

    @Test
    public void erweiterung_teilstueck() {
        int[] r = {5, 2, 9, 1, 6, 3};
        assertEquals("{2, 9, 1}", Anzeige.text(TeileUndHerrsche.teilstueck(r, 1, 4)), "teilstueck({5, 2, 9, 1, 6, 3}, 1, 4) = {2, 9, 1} - bis (Index 4) gehoert NICHT dazu");
        assertEquals("{5, 2, 9}", Anzeige.text(TeileUndHerrsche.teilstueck(r, 0, 3)), "teilstueck(r, 0, 3) = {5, 2, 9}");
        assertEquals("{1, 6, 3}", Anzeige.text(TeileUndHerrsche.teilstueck(r, 3, 6)), "teilstueck(r, 3, 6) = {1, 6, 3} (bis 6 = r.length)");
        assertEquals("{}", Anzeige.text(TeileUndHerrsche.teilstueck(r, 2, 2)), "teilstueck(r, 2, 2) ist leer: Laenge bis - von = 0");
        assertEquals("{5, 2, 9, 1, 6, 3}", Anzeige.text(r), "teilstueck darf r nicht veraendern");
        assertFalse(TeileUndHerrsche.teilstueck(r, 0, 6) == r, "teilstueck(r, 0, 6) muss eine NEUE Reihung liefern (Kopie), nicht r selbst");
    }

    @Test
    public void erweiterung_verschmelze() {
        int[] a = {2, 5, 9};
        int[] b = {1, 3, 6};
        assertEquals("{1, 2, 3, 5, 6, 9}", Anzeige.text(TeileUndHerrsche.verschmelze(a, b)), "verschmelze({2, 5, 9}, {1, 3, 6}) = {1, 2, 3, 5, 6, 9}");
        assertEquals("{2, 5, 9}", Anzeige.text(a), "verschmelze darf a nicht veraendern");
        int[] c = {1, 2};
        int[] d = {3, 4, 5};
        assertEquals("{1, 2, 3, 4, 5}", Anzeige.text(TeileUndHerrsche.verschmelze(c, d)), "verschmelze({1, 2}, {3, 4, 5}): a ist zuerst aufgebraucht - den REST von b anhaengen!");
        assertEquals("{1, 2, 3, 4, 5}", Anzeige.text(TeileUndHerrsche.verschmelze(d, c)), "verschmelze({3, 4, 5}, {1, 2}): b ist zuerst aufgebraucht - den REST von a anhaengen!");
    }

    @Test
    public void erweiterung_verschmelze_randfaelle() {
        int[] leer = new int[0];
        int[] b = {4, 7};
        assertEquals("{4, 7}", Anzeige.text(TeileUndHerrsche.verschmelze(leer, b)), "verschmelze({}, {4, 7}) = {4, 7}");
        assertEquals("{4, 7}", Anzeige.text(TeileUndHerrsche.verschmelze(b, leer)), "verschmelze({4, 7}, {}) = {4, 7}");
        int[] c = {1, 3, 3};
        int[] d = {2, 3};
        assertEquals("{1, 2, 3, 3, 3}", Anzeige.text(TeileUndHerrsche.verschmelze(c, d)), "verschmelze({1, 3, 3}, {2, 3}) = {1, 2, 3, 3, 3} - gleiche Werte duerfen nicht verloren gehen");
    }

    @Test
    public void erweiterung_mergeSort() {
        int[] r = {5, 2, 9, 1, 6, 3};
        int[] s = TeileUndHerrsche.mergeSort(r);
        assertEquals("{1, 2, 3, 5, 6, 9}", Anzeige.text(s), "mergeSort({5, 2, 9, 1, 6, 3}) = {1, 2, 3, 5, 6, 9}");
        assertEquals("{5, 2, 9, 1, 6, 3}", Anzeige.text(r), "mergeSort liefert eine NEUE Reihung - r selbst bleibt unveraendert");
        int[] r8 = {7, 3, 9, 2, 8, 5, 1, 6};
        assertEquals("{1, 2, 3, 5, 6, 7, 8, 9}", Anzeige.text(TeileUndHerrsche.mergeSort(r8)), "mergeSort({7, 3, 9, 2, 8, 5, 1, 6}) = {1, 2, 3, 5, 6, 7, 8, 9}");
    }

    @Test
    public void erweiterung_mergeSort_randfaelle() {
        int[] zwei = {2, 1};
        assertEquals("{1, 2}", Anzeige.text(TeileUndHerrsche.mergeSort(zwei)), "mergeSort({2, 1}) = {1, 2}. Bei StackOverflowError: mitte = r.length / 2 - sonst ist eine Haelfte leer und die andere so lang wie vorher");
        int[] eins = {7};
        int[] e = TeileUndHerrsche.mergeSort(eins);
        assertEquals("{7}", Anzeige.text(e), "mergeSort({7}) = {7} (Basisfall)");
        assertFalse(e == eins, "Basisfall: mergeSort muss eine KOPIE liefern, nicht r selbst");
        assertEquals("{}", Anzeige.text(TeileUndHerrsche.mergeSort(new int[0])), "mergeSort({}) = {} (Basisfall)");
        int[] dopp = {3, 1, 3, 1, 2};
        assertEquals("{1, 1, 2, 3, 3}", Anzeige.text(TeileUndHerrsche.mergeSort(dopp)), "mergeSort({3, 1, 3, 1, 2}) = {1, 1, 2, 3, 3} - doppelte Werte");
    }

    @Test
    public void experte_zerlege() {
        int[] r = {5, 3, 8, 1, 9, 2};
        TeileUndHerrsche.vergleiche = 0;
        int p = TeileUndHerrsche.zerlege(r, 0, 5);
        assertEquals("{2, 3, 1, 5, 9, 8}", Anzeige.text(r), "zerlege({5, 3, 8, 1, 9, 2}, 0, 5) mit Pivot 5 (links) - genau nach dem Verfahren tauschen, sonst entsteht eine andere Reihenfolge");
        assertEquals(3, p, "zerlege liefert die Endposition des Pivots 5: Index 3");
        assertEquals(5, TeileUndHerrsche.vergleiche, "zerlege(r, 0, 5): 5 Vergleiche (i = 1 bis 5)");
    }

    @Test
    public void experte_zerlege_teilbereich() {
        int[] r = {9, 1, 6, 4, 8, 2, 7, 0};
        TeileUndHerrsche.vergleiche = 0;
        int p = TeileUndHerrsche.zerlege(r, 2, 6);
        assertEquals("{9, 1, 2, 4, 6, 8, 7, 0}", Anzeige.text(r), "zerlege(r, 2, 6): nur r[2] bis r[6] zerlegen, Pivot r[2] = 6; r[0], r[1] und r[7] bleiben stehen");
        assertEquals(4, p, "zerlege(r, 2, 6): Das Pivot 6 landet an Index 4");
        assertEquals(4, TeileUndHerrsche.vergleiche, "zerlege(r, 2, 6): 4 Vergleiche (i = 3 bis 6)");
    }

    @Test
    public void experte_zerlege_gleicheWerte() {
        int[] r = {4, 4, 2, 4, 1};
        TeileUndHerrsche.vergleiche = 0;
        int p = TeileUndHerrsche.zerlege(r, 0, 4);
        assertEquals("{1, 2, 4, 4, 4}", Anzeige.text(r), "zerlege({4, 4, 2, 4, 1}, 0, 4): Nur ECHT kleinere Werte (r[i] < pivot) wandern nach links - Werte gleich dem Pivot bleiben rechts");
        assertEquals(2, p, "zerlege({4, 4, 2, 4, 1}, 0, 4): Das Pivot 4 landet an Index 2");
        assertEquals(4, TeileUndHerrsche.vergleiche, "zerlege(r, 0, 4): 4 Vergleiche");
    }

    @Test
    public void experte_quickSort() {
        int[] r = {4, 8, 2, 9, 3, 7, 1};
        TeileUndHerrsche.vergleiche = 0;
        TeileUndHerrsche.quickSort(r);
        assertEquals("{1, 2, 3, 4, 7, 8, 9}", Anzeige.text(r), "quickSort({4, 8, 2, 9, 3, 7, 1}) sortiert r selbst (in-place)");
        assertEquals(11, TeileUndHerrsche.vergleiche, "quickSort({4, 8, 2, 9, 3, 7, 1}): 6 + 2 + 1 + 2 = 11 Vergleiche - pruefe die Grenzen p - 1 und p + 1");
        int[] d = {3, 1, 3, 2, 3};
        TeileUndHerrsche.quickSort(d);
        assertEquals("{1, 2, 3, 3, 3}", Anzeige.text(d), "quickSort({3, 1, 3, 2, 3}) = {1, 2, 3, 3, 3} - doppelte Werte");
    }

    @Test
    public void experte_quickSort_schlechtesterFall() {
        int[] r = {1, 2, 3, 4, 5, 6};
        TeileUndHerrsche.vergleiche = 0;
        TeileUndHerrsche.quickSort(r);
        assertEquals("{1, 2, 3, 4, 5, 6}", Anzeige.text(r), "Bereits sortiert: bleibt sortiert");
        assertEquals(15, TeileUndHerrsche.vergleiche, "Bereits sortiert, n = 6: Das Pivot (links) ist immer das kleinste -> 5 + 4 + 3 + 2 + 1 = 15 = n(n-1)/2 Vergleiche (schlechtester Fall)");
        int[] u = {6, 5, 4, 3, 2, 1};
        TeileUndHerrsche.vergleiche = 0;
        TeileUndHerrsche.quickSort(u);
        assertEquals("{1, 2, 3, 4, 5, 6}", Anzeige.text(u), "quickSort({6, 5, 4, 3, 2, 1}) = {1, 2, 3, 4, 5, 6}");
        assertEquals(15, TeileUndHerrsche.vergleiche, "Absteigend sortiert, n = 6: ebenfalls 15 Vergleiche");
    }

    @Test
    public void experte_quickSort_randfaelle() {
        int[] eins = {5};
        TeileUndHerrsche.vergleiche = 0;
        TeileUndHerrsche.quickSort(eins);
        int[] leer = new int[0];
        TeileUndHerrsche.quickSort(leer);
        assertEquals(0, TeileUndHerrsche.vergleiche, "Ein Element oder leere Reihung: nichts zu tun, 0 Vergleiche (Basisfall lo >= hi)");
        int[] zwei = {9, 4};
        TeileUndHerrsche.quickSort(zwei);
        assertEquals("{4, 9}", Anzeige.text(zwei), "quickSort({9, 4}) = {4, 9}");
        assertEquals(1, TeileUndHerrsche.vergleiche, "quickSort({9, 4}): genau 1 Vergleich");
    }
}


