    // ---------------- Deko 4: Sierpinski-Dreieck (Erweiterung) ----------------
    //
    // Idee: Ein Sierpinski-Dreieck besteht aus drei halb so grossen
    // Sierpinski-Dreiecken - eins an jeder Ecke.
    //
    // Der Basisfall zeichnet ein einfaches Dreieck: dreimal vorwaerts und
    // um 120 Grad nach LINKS drehen. Weil die Turtle anfangs nach rechts
    // blickt, zeigt die Spitze nach oben.
    //
    // Rekursionsschritt - dreimal wiederholen:
    //   1. sierpinski(t, laenge / 2, tiefe - 1);   (Teildreieck an dieser Ecke)
    //   2. Stift anheben, die GANZE Seite laenge vorwaerts zur naechsten
    //      Ecke laufen, Stift absenken
    //   3. um 120 Grad nach links drehen (wie im Basisfall!)
    // Danach steht die Turtle wieder am Start und blickt nach rechts.

    static void sierpinski(Turtle t, double laenge, int tiefe) {
        aufrufe++;
        if (tiefe == 0) {
